import { readFileSync } from 'node:fs';

const file = process.argv[2];
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);

for (const line of lines) {
  let obj;
  try { obj = JSON.parse(line); } catch { continue; }
  const ts = obj.timestamp || '';
  const type = obj.type || obj.role || '?';
  let summary = '';
  const msg = obj.message || obj;
  const content = msg.content;
  if (Array.isArray(content)) {
    summary = content.map(c => {
      if (c.type === 'text') return `TEXT: ${c.text.slice(0, 200).replace(/\n/g, ' ')}`;
      if (c.type === 'tool_use') return `TOOL_USE(${c.name}): ${JSON.stringify(c.input).slice(0, 200)}`;
      if (c.type === 'tool_result') {
        const t = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
        return `TOOL_RESULT: ${(t||'').slice(0, 150).replace(/\n/g, ' ')}`;
      }
      return `OTHER(${c.type})`;
    }).join(' | ');
  } else if (typeof content === 'string') {
    summary = content.slice(0, 200).replace(/\n/g, ' ');
  }
  console.log(`[${ts}] ${type}: ${summary}`);
}

